import { saveState, loadState } from '../persistence/state.store';

let saved = loadState();

export class Graph {
 nodes = new Map(saved?.nodes || []);
 edges:any[] = saved?.edges || [];

 addNode(n:any){ this.nodes.set(n.id,n); this.persist(); }
 addEdge(e:any){ this.edges.push(e); this.persist(); }

 persist(){ saveState({ nodes:[...this.nodes], edges:this.edges }); }
}

